function aiMemoryMoveOpen(cid){const cs=(S.contacts||[]).filter(c=>c&&!c.deleted);if(!cs.length){toast('先在微信里创建一个角色');return;}const selected=getC(cid)?cid:cs[0].id;openModal(`<h3>AI 记忆搬家</h3><div class="hint" style="line-height:1.75">选择记忆属于哪个角色，再上传从其他 AI 导出的文件。导入只会追加；不会覆盖现有聊天、人设和记忆。</div><div class="field"><label>搬给哪个角色</label><select id="aim_cid">${cs.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.remark||c.name)}</option>`).join('')}</select></div><div class="field"><label>记忆文件</label><input id="aim_file" type="file" accept=".json,.docx,.doc,.txt,.md,.csv,.html,.htm,.rtf,application/json,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain"></div><div class="hint">支持现成记忆、总结和聊天资料。不会上传到服务器，也不会调用付费模型；文件只在当前设备解析。</div><div id="aim_status" style="min-height:18px;margin-top:8px;color:#9aa;font-size:12px"></div><div class="btns" style="margin-top:12px"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" id="aim_go" onclick="aiMemoryMoveAnalyze()">读取并预览</button></div>`);}
