async function aiMemoryMoveCommit(){const p=_aiMemoryMovePreview,c=p&&getC(p.cid);if(!p||!c)return;const btn=$('#aim_commit');if(btn){btn.disabled=true;btn.textContent='正在保存…';}const docs=aiMemoryDocs(c),doc={id:uid(),name:String(p.name||'外部AI记忆').slice(0,180),format:p.format||'',size:p.size||0,charCount:p.charCount||0,importedAt:Date.now(),chunks:p.chunks.slice()},at=docs.length;docs.push(doc);try{if(!await saveNowAsync())throw new Error('浏览器没有足够存储空间');_aiMemoryMovePreview=null;closeModal();toast('已给 '+(c.remark||c.name)+' 导入 '+doc.chunks.length+' 条外部记忆');}catch(e){docs.splice(at,1);if(btn){btn.disabled=false;btn.textContent='确认导入全部';}toast('导入保存失败：'+((e&&e.message)||'请检查手机剩余空间'));}}
