function cleanChatMediaStore(store){const r={n:0,bytes:0};if(!store||typeof store!=='object')return r;
  Object.keys(store).forEach(k=>{if(k==='__idb'||k==='id')return;const a=store[k];if(!Array.isArray(a))return;a.forEach(m=>mergeCacheStat(r,cleanChatMediaMsg(m)));});
  return r;}
function cleanPfMediaMsg(m){const r={n:0,bytes:0};if(!m||typeof m!=='object')return r;const body=m.body||m.text||m.content,p=pfUnpack(body);if(!p||p.type!=='image'||!p.img)return r;
  r.bytes+=cacheMediaSize(p.img);p.img='';p.cleaned=1;const nb=pfPack(p);if(m.body!=null)m.body=nb;else if(m.text!=null)m.text=nb;else m.content=nb;r.n++;return r;}
function cleanPfMediaStore(store){const r={n:0,bytes:0};if(!store||typeof store!=='object')return r;
  Object.keys(store).forEach(k=>{if(k==='__idb'||k==='id')return;const a=store[k];if(!Array.isArray(a))return;a.forEach(m=>mergeCacheStat(r,cleanPfMediaMsg(m)));});
  return r;}
function cacheSizeText(bytes){bytes=+bytes||0;if(bytes>=1048576)return (bytes/1048576).toFixed(2)+'MB';if(bytes>=1024)return (bytes/1024).toFixed(1)+'KB';return bytes?bytes+'B':'';}
async function clearRoleCacheKeepBeauty(){if(!await uiConfirm('清理聊天图片和语音？\n\n会清掉：聊天记录里的图片缓存、语音音频（文字都保留），以及已经删除的消息和通话留下来的语音。\n\n不会删除：角色、记忆、文字聊天、朋友圈、信箱、电话短信、真人好友/群聊、壁纸、美化图片、音乐背景。',{danger:false}))return;
  if(_bootImagesPromise)try{await _bootImagesPromise;}catch(_){}
  const total={n:0,bytes:0};
  mergeCacheStat(total,cleanChatMediaStore(S.messages));
  const p=phoneFriendState();mergeCacheStat(total,cleanPfMediaStore(p.messages));mergeCacheStat(total,cleanPfMediaStore(p.groupMessages));
  try{imgGC();}catch(_){}
  save(0);let orphan={n:0};try{orphan=await audioOrphanGC();}catch(_){}try{render();}catch(_){}
  const parts=[];if(total.n)parts.push('聊天媒体 '+total.n+' 项'+(total.bytes?'（约 '+cacheSizeText(total.bytes)+'）':''));if(orphan.n)parts.push('已删除消息留下的语音 '+orphan.n+' 段');
  toast(parts.length?'已清理：'+parts.join('，'):'没有发现可清的聊天媒体，已整理旧缓存引用',3200);}
/* 删掉消息或通话后，它们的语音（__audio_）以前一直留着，imgGC 跳过所有 __ 开头的键。这里只删没有任何地方引用的语音：
   引用从内存里的全部数据和每个长聊天库原文里找；任何一处读不到就整个放弃，刚写进去 10 分钟内的不删。只在手动清理时运行。 */
async function audioOrphanGC(){if(_bootImagesPromise)try{await _bootImagesPromise;}catch(_){}
  let all;try{all=await imgKeys();}catch(_){return {n:0,failed:true};}const audio=(all||[]).map(String).filter(k=>k.indexOf('__audio_')===0);if(!audio.length)return {n:0};
  const refs=new Set(),scan=t=>{String(t||'').replace(/idb-audio:([^"'\\\s]+)/g,(w,id)=>{refs.add('__audio_'+id);return w;});};
  try{scan(JSON.stringify(S));}catch(_){return {n:0,failed:true};}
  for(const k of all.map(String).filter(k=>/^__(?:messages|pf_messages|pf_group_messages)/.test(k))){try{scan(await imgGetIDB(k));}catch(_){return {n:0,failed:true};}}
  const now=Date.now();let n=0;for(const k of audio){if(refs.has(k))continue;const at=_audioPutAt.get(k);if(at&&now-at<600000)continue;try{await imgDel(k);n++;}catch(_){}}return {n};}
function clearStoreVoiceAudio(store){try{Object.keys(store||{}).forEach(k=>{if(k==='__idb'||k==='id')return;const a=store[k];if(Array.isArray(a))a.forEach(m=>{if(m&&m.type==='voice')clearVoiceAudio(m);});});}catch(_){}}
async function clearAllChatRecords(){if(!await uiConfirm('清空所有聊天记录？\n\n会清空：角色微信聊天、小手机真人好友私聊、真人群聊。\n不会删除：角色、真人好友、群成员、记忆、人设、头像、美化图片。\n\n清空后无法恢复，建议先导出备份。',{danger:true}))return;
  if(!await uiConfirm('最后确认：真的清空所有聊天记录吗？\n好友和群还在，但聊天内容会变空。',{danger:true}))return;
  if(_bootImagesPromise)try{await _bootImagesPromise;}catch(_){}
  const p=phoneFriendState(),now=Date.now();
  clearStoreVoiceAudio(S.messages);S.messages={};try{delete _heavy.messages;_heavyReady.delete('messages');await imgDel('__messages');}catch(_){}
  p.messages={};p.groupMessages={};p.friendRead={};p.groupRead={};p.clearBefore=p.clearBefore||{};p.groupClearBefore=p.groupClearBefore||{};
  (p.friends||[]).forEach(f=>{const id=(''+(f.phone_id||f.id||'')).toUpperCase();if(id)p.clearBefore[id]=now;});
  (p.groups||[]).forEach(g=>{const gid=g&&(g.group_id||g.id);if(gid)p.groupClearBefore[gid]=now;});
  p.lastSync=now;p._forceFullSync=0;
  try{const key=pfMsgStoreKey();delete _heavy['pfMessages:'+key];_heavyReady.delete('pfMessages:'+key);await imgDel(key);}catch(_){}
  try{const key=pfGroupMsgStoreKey();delete _heavy['pfGroupMessages:'+key];_heavyReady.delete('pfGroupMessages:'+key);await imgDel(key);}catch(_){}
  try{imgGC();}catch(_){}
  save(0);try{closeModal();}catch(_){}try{render();}catch(_){}
  toast('已清空所有聊天记录，角色/好友/群聊都保留了');}
/* ---------- ☁️ 云同步 ---------- */
function cloudId(){S.settings=S.settings||{};if(!S.settings.cloudId)S.settings.cloudId='yb_'+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2)+Date.now().toString(36);save();return S.settings.cloudId;}
const PRIVATE_MIRROR_MODE='private-primary',PRIVATE_MIRROR_ROLLBACK_KEY='__private_mirror_rollback';
let _privateMirrorBusy=false,_privateMirrorTimer=0,_privateMirrorCandidate=null,_privateMirrorSeen='';
function privateMirrorMeta(d,row){const m=d&&d._privateMirrorMeta;if(!m||m.mode!==PRIVATE_MIRROR_MODE||m.source!=='private-ios')return null;const revision=Math.max(0,Math.floor(+m.revision||0)),capturedAt=Math.max(0,+m.capturedAt||0),updatedAt=Math.max(capturedAt,Date.parse(m.updatedAt||row&&row.updated_at||'')||0);return revision?{mode:PRIVATE_MIRROR_MODE,source:'private-ios',revision,capturedAt,updatedAt,sourceBuild:String(m.sourceBuild||'')}:null;}
async function cloudFetchRow(idOverride){const U=cloudUrl(),K=cloudKey();if(!U||!K)throw new Error('还没填云地址/Key，先在云同步里填一下');const id=idOverride||cloudId(),r=await fetch(U+'/rest/v1/backups?id=eq.'+encodeURIComponent(id)+'&select=data,ver,updated_at',{headers:{'apikey':K,'Authorization':'Bearer '+K}});if(!r.ok)throw new Error('HTTP '+r.status);const rows=await r.json();if(!rows||!rows.length)return null;let data;try{data=JSON.parse(rows[0].data);}catch(_){throw new Error('云端数据格式不对');}return {id,data,ver:rows[0].ver,updated_at:rows[0].updated_at};}
async function cloudWriteRow(id,data,expectedUpdatedAt){const U=cloudUrl(),K=cloudKey(),updatedAt=new Date().toISOString();let url=U+'/rest/v1/backups',method='POST',prefer='resolution=merge-duplicates,return=representation',body={id,data:JSON.stringify(data),ver:APP_VER,updated_at:updatedAt};if(expectedUpdatedAt){method='PATCH';url+='?id=eq.'+encodeURIComponent(id)+'&updated_at=eq.'+encodeURIComponent(expectedUpdatedAt);prefer='return=representation';delete body.id;}const r=await fetch(url,{method,headers:{'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json','Prefer':prefer},body:JSON.stringify(body)});if(!r.ok){let t='';try{t=await r.text();}catch(_){}throw new Error('HTTP '+r.status+(t?(' '+t.slice(0,120)):''));}if(expectedUpdatedAt){let rows=[];try{rows=await r.json();}catch(_){}if(!rows.length)throw new Error('云端修订已变化，本次没有覆盖，请重新同步');}return updatedAt;}
async function privatePrimaryMirrorUpload(snapshot,opt){if(!privateNativeAppOn()||!cloudUrl()||!cloudKey())return {skipped:true};opt=opt||{};const id=cloudId(),remote=await cloudFetchRow(id),remoteMeta=remote&&privateMirrorMeta(remote.data,remote);if(remote&&!remoteMeta&&!opt.allowLegacy)throw new Error('网页版已有旧格式备份，首次绑定未覆盖；请在云同步里确认后再建立私人主设备镜像');const localRevision=Math.max(0,+((S.settings||{}).privateMirrorRevision)||0),revision=Math.max(localRevision,remoteMeta&&remoteMeta.revision||0)+1,capturedAt=Math.max(Date.now(),+snapshot._persistedAt||0),meta={mode:PRIVATE_MIRROR_MODE,source:'private-ios',revision,capturedAt,updatedAt:new Date().toISOString(),sourceBuild:String(window.__SMALL_PHONE_PRIVATE_BUILD__||APP_VER)},data=JSON.parse(JSON.stringify(snapshot));data._privateMirrorMeta=meta;data.settings=data.settings||{};data.settings.privateMirrorRevision=revision;data.settings.privateMirrorSource='private-ios';await cloudWriteRow(id,data,remote&&remote.updated_at);S.settings=S.settings||{};S.settings.privateMirrorRevision=revision;S.settings.privateMirrorSource='private-ios';S.settings.privateMirrorLastUploadedAt=Date.now()+5000;S.settings.cloudLast=Date.now();await saveNowAsync();return {uploaded:true,revision,bytes:JSON.stringify(data).length};}
function privateMirrorLocalDirty(meta){const applied=Math.max(0,+((S.settings||{}).privateMirrorAppliedRevision)||0),appliedAt=Math.max(0,+((S.settings||{}).privateMirrorAppliedAt)||0);if(!applied)return recoveryStateMeaningful(recoveryStateStats(S));if(meta.revision<=applied)return false;return (+S._persistedAt||0)>appliedAt+2500;}
async function privateMirrorSaveRollback(reason){const state=await fullBackupState(),savedAt=Date.now(),json=JSON.stringify(state);await imgPut(PRIVATE_MIRROR_ROLLBACK_KEY,{ver:1,savedAt,reason:reason||'private-primary',json});return {savedAt,bytes:json.length};}
async function privateMirrorApplyRemote(data,row,manual,targetId){const meta=privateMirrorMeta(data,row);if(!meta)throw new Error('这不是私人主设备镜像');await privateMirrorSaveRollback(manual?'manual-private-restore':'private-mirror-update');const keep={cloudUrl:cloudUrl(),cloudKey:cloudKey(),cloudId:targetId||cloudId(),cloudAuto:!!(S.settings&&S.settings.cloudAuto)},next=mergeStateData(data,{keepPhoneFriend:true});next.settings=next.settings||{};Object.assign(next.settings,keep,{privateMirrorAppliedRevision:meta.revision,privateMirrorAppliedAt:Date.now(),privateMirrorSource:'private-ios',privateMirrorRevision:Math.max(+next.settings.privateMirrorRevision||0,meta.revision),cloudLast:Date.now()});S=next;normalizeLoadedState();phoneFriendState();if(!await saveNowAsync())throw new Error('私人镜像写入网页本机失败');_privateMirrorCandidate=null;render();return meta;}
async function privateMirrorRestoreRollback(){const rec=await imgGet(PRIVATE_MIRROR_ROLLBACK_KEY);if(!rec||!rec.json){toast('还没有可撤回的网页快照');return;}if(!await uiConfirm('撤回到应用私人镜像之前的网页本机数据？'))return;let d;try{d=JSON.parse(rec.json);}catch(_){toast('撤回快照已损坏');return;}S=mergeStateData(d,{keepPhoneFriend:true});normalizeLoadedState();phoneFriendState();await saveNowAsync();closeModal();render();toast('已撤回到同步前的网页本机快照');}
async function privateMirrorUsePrivate(){const c=_privateMirrorCandidate;if(!c)return;closeModal();toast('正在保留私人版本并建立网页镜像…');try{const meta=await privateMirrorApplyRemote(c.data,c.row,true);toast('网页已同步私人版本 r'+meta.revision+'；原网页快照可撤回');}catch(e){toast('同步失败：'+e.message);}}
function privateMirrorConflictModal(candidate,first){_privateMirrorCandidate=candidate;const m=candidate.meta;openModal(`<h3>私人版本发现更新</h3><div class="hint" style="line-height:1.8">${first?'这是首次绑定，':'网页本机也有尚未合并的改动，'}系统没有静默覆盖任何一端。<br><br>私人版本：<b>r${m.revision}</b> · ${esc(fmtDT(m.capturedAt||m.updatedAt))}<br>默认建议保留私人版本；应用前会保存当前网页快照，可随时撤回。</div><div class="btns"><button class="btn p" onclick="privateMirrorUsePrivate()">保留私人版本</button><button class="btn g" onclick="closeModal();toast('网页本机改动已暂留，且不会上传覆盖私人版本')">暂留网页本机</button></div><button class="btn g" style="margin-top:8px" onclick="privateMirrorRestoreRollback()">撤回上次镜像</button><div class="hint" style="margin-top:8px">聊天、角色、记忆、朋友圈、钱包和常规设置会同步；放映室原生大视频、系统相册原文件等大型媒体不属于网页镜像范围。</div>`);}
async function privatePrimaryMirrorCheck(opt){if(privateNativeAppOn()||_privateMirrorBusy||!cloudUrl()||!cloudKey())return null;opt=opt||{};_privateMirrorBusy=true;try{const row=Object.prototype.hasOwnProperty.call(opt,'row')?opt.row:await cloudFetchRow(),meta=row&&privateMirrorMeta(row.data,row);if(!meta)return null;const applied=Math.max(0,+((S.settings||{}).privateMirrorAppliedRevision)||0),key=meta.revision+':'+meta.updatedAt;if(meta.revision<=applied)return {current:true,meta};if(privateMirrorLocalDirty(meta)){if(_privateMirrorSeen!==key||opt.manual){_privateMirrorSeen=key;privateMirrorConflictModal({data:row.data,row,meta},!applied);}return {conflict:true,meta};}const appliedMeta=await privateMirrorApplyRemote(row.data,row,false);if(!opt.silent)toast('网页已自动同步私人版本 r'+appliedMeta.revision);return {applied:true,meta:appliedMeta};}finally{_privateMirrorBusy=false;}}
function privatePrimaryMirrorWake(){if(privateNativeAppOn()||_privateMirrorTimer)return;_privateMirrorTimer=setTimeout(()=>{_privateMirrorTimer=0;privatePrimaryMirrorCheck({silent:true}).catch(()=>{});},1200);}
async function privateMirrorPublishNow(){if(!privateNativeAppOn()){toast('请在私人 App 里执行这一步');return;}if(!cloudUrl()||!cloudKey()){toast('云连接尚未配置，请先保存云地址和 Key');return;}toast('正在把私人 App 当前数据发布到网页版…');try{if(!await saveNowAsync())throw new Error('私人 App 当前数据尚未保存完成');const snapshot=await fullBackupState();snapshot._persistedAt=Math.max(+snapshot._persistedAt||0,Date.now());const result=await privatePrimaryMirrorUpload(snapshot,{allowLegacy:true});if(!result||result.uploaded!==true)throw new Error('网页版镜像没有写入');S.settings.cloudAuto=true;await saveNowAsync();toast('✅ 已发布到网页版 · 私人版本 r'+result.revision);cloudSyncModal();}catch(e){toast('发布失败：'+String(e&&e.message||e));}}
async function cloudApplyLegacyRow(data,row,targetId){if(!data||!data.settings)throw new Error('云端数据格式不对');await privateMirrorSaveRollback('manual-web-cloud-restore');const keep={cloudUrl:cloudUrl(),cloudKey:cloudKey(),cloudId:targetId||cloudId(),cloudAuto:!!(S.settings&&S.settings.cloudAuto)},next=mergeStateData(data,{keepPhoneFriend:true});next.settings=next.settings||{};Object.assign(next.settings,keep,{cloudLast:Date.now()});S=next;normalizeLoadedState();phoneFriendState();if(!await saveNowAsync())throw new Error('网页云备份写入本机失败');return row&&row.updated_at||'';}
async function privateMirrorPullNow(){if(privateNativeAppOn()){toast('私人 App 不会从网页版反向恢复；请使用手机号私人备份');return;}if(!cloudUrl()||!cloudKey()){toast('云连接尚未配置，请先保存云地址和 Key');return;}toast('正在读取云端版本…');try{const row=await cloudFetchRow(),meta=row&&privateMirrorMeta(row.data,row);if(!row)throw new Error('云端还没有找到备份');if(meta){const applied=await privateMirrorApplyRemote(row.data,row,true);S.settings.cloudAuto=true;await saveNowAsync();closeModal();render();toast('✅ 网页已读取私人版本 r'+applied.revision);}else{await cloudApplyLegacyRow(row.data,row,cloudId());closeModal();render();toast('✅ 网页已读取原有云备份；读取前快照可撤回');}}catch(e){toast('读取失败：'+String(e&&e.message||e));}}
